import java.io.*;
import java.util.*;

public class Main {
    static class Node {
        int data;
        Node next;
        Node(int data) { this.data = data; }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        if (n <= 0) {
            System.out.println();
            return;
        }
        String[] parts = br.readLine().trim().split("\\s+");

        Node head = null, tail = null;
        for (int i = 0; i < n; i++) {
            int val = Integer.parseInt(parts[i]);
            Node newNode = new Node(val);
            if (head == null) {
                head = tail = newNode;
            } else {
                tail.next = newNode;
                tail = newNode;
            }
        }

        head = bucketSort(head, n);

        StringBuilder sb = new StringBuilder();
        Node curr = head;
        while (curr != null) {
            sb.append(curr.data);
            if (curr.next != null) sb.append(" ");
            curr = curr.next;
        }
        System.out.println(sb.toString());
    }

    static Node bucketSort(Node head, int n) {
        if (head == null || head.next == null) return head;

        int min = head.data, max = head.data;
        for (Node curr = head; curr != null; curr = curr.next) {
            if (curr.data < min) min = curr.data;
            if (curr.data > max) max = curr.data;
        }

        int range = max - min + 1;
        int bucketCount = Math.max(1, (int) Math.ceil(Math.sqrt(n)));

        Node[] buckets = new Node[bucketCount];
        Node[] bucketTails = new Node[bucketCount];

        int buckSize = Math.max(1, range / bucketCount);

        for (Node curr = head; curr != null; ) {
            Node next = curr.next;
            curr.next = null;

            int buckIdx = (curr.data - min) / buckSize;
            if (buckIdx >= bucketCount) buckIdx = bucketCount - 1;
            if (buckIdx < 0) buckIdx = 0;

            if (buckets[buckIdx] == null) {
                buckets[buckIdx] = curr;
                bucketTails[buckIdx] = curr;
            } else {
                bucketTails[buckIdx].next = curr;
                bucketTails[buckIdx] = curr;
            }

            curr = next;
        }

        Node resultHead = null, resultTail = null;
        for (int i = 0; i < bucketCount; i++) {
            if (buckets[i] != null) {
                Node sorted = insertionSort(buckets[i]);
                if (resultHead == null) {
                    resultHead = sorted;
                    resultTail = bucketTails[i];
                } else {
                    resultTail.next = sorted;
                    for (Node temp = sorted; temp.next != null; temp = temp.next);
                    resultTail = temp;
                }
            }
        }

        return resultHead;
    }

    static Node insertionSort(Node head) {
        if (head == null || head.next == null) return head;

        Node sorted = null;
        while (head != null) {
            Node next = head.next;
            sorted = sortedInsert(sorted, head);
            head = next;
        }
        return sorted;
    }

    static Node sortedInsert(Node head, Node node) {
        if (head == null || node.data < head.data) {
            node.next = head;
            return node;
        }

        Node curr = head;
        while (curr.next != null && curr.next.data < node.data) {
            curr = curr.next;
        }

        node.next = curr.next;
        curr.next = node;
        return head;
    }
}
